// accumulateTokenUsage sums token usage from a new checkpoint into the existing total.
// Returns the accumulated total, handling nil cases appropriately.
func accumulateTokenUsage(existing, additional *checkpoint.TokenUsage) *checkpoint.TokenUsage {
	if additional == nil {
		return existing
	}
	if existing == nil {
		// Copy to avoid modifying the original
		return &checkpoint.TokenUsage{
			InputTokens:         additional.InputTokens,
			CacheCreationTokens: additional.CacheCreationTokens,
			CacheReadTokens:     additional.CacheReadTokens,
			OutputTokens:        additional.OutputTokens,
			APICallCount:        additional.APICallCount,
			SubagentTokens:      additional.SubagentTokens,
		}
	}
	return &checkpoint.TokenUsage{
		InputTokens:         existing.InputTokens + additional.InputTokens,
		CacheCreationTokens: existing.CacheCreationTokens + additional.CacheCreationTokens,
		CacheReadTokens:     existing.CacheReadTokens + additional.CacheReadTokens,
		OutputTokens:        existing.OutputTokens + additional.OutputTokens,
		APICallCount:        existing.APICallCount + additional.APICallCount,
		SubagentTokens:      accumulateTokenUsage(existing.SubagentTokens, additional.SubagentTokens),
	}
}

