   150→// extractSessionData extracts session data from the shadow branch.
   151→// startLine specifies the first line to include (0 = all lines, for incremental condensation).
   152→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
   153→func (s *ManualCommitStrategy) extractSessionData(repo *git.Repository, shadowRef plumbing.Hash, sessionID string, startLine int, filesTouched []string) (*ExtractedSessionData, error) {
   154→	commit, err := repo.CommitObject(shadowRef)
   155→	if err != nil {
   156→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   157→	}
   158→
   159→	tree, err := commit.Tree()
   160→	if err != nil {
   161→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   162→	}
