   164→	data := &ExtractedSessionData{}
   165→	// sessionID is already an "entire session ID" (with date prefix), so construct path directly
   166→	// Don't use paths.SessionMetadataDir which would add another date prefix
   167→	metadataDir := paths.EntireMetadataDir + "/" + sessionID
   168→
   169→	// Extract transcript
   170→	var fullTranscript string
   171→	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
   172→		if content, contentErr := file.Contents(); contentErr == nil {
   173→			fullTranscript = content
   174→		}
   175→	} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
   176→		if content, contentErr := file.Contents(); contentErr == nil {
   177→			fullTranscript = content
   178→		}
   179→	}
   180→
   181→	// Split into lines and filter
   182→	if fullTranscript != "" {
   183→		allLines := strings.Split(fullTranscript, "\n")
   184→
   185→		// Trim trailing empty lines (from final \n in JSONL)
   186→		for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   187→			allLines = allLines[:len(allLines)-1]
   188→		}
   189→
   190→		data.FullTranscriptLines = len(allLines)
   191→
   192→		// Get only lines from startLine onwards for this condensation
   193→		if startLine < len(allLines) {
   194→			newLines := allLines[startLine:]
   195→			data.Transcript = []byte(strings.Join(newLines, "\n"))
   196→
   197→			// Extract prompts from the new portion only
   198→			data.Prompts = extractUserPromptsFromLines(newLines)
   199→
   200→			// Generate context from prompts
   201→			data.Context = generateContextFromPrompts(data.Prompts)
   202→		}
   203→	}
   204→
   205→	// Use tracked files from session state (not all files in tree)
