   211→// extractUserPromptsFromLines extracts user prompts from JSONL transcript lines.
   212→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   213→func extractUserPromptsFromLines(lines []string) []string {
   214→	var prompts []string
   215→	for _, line := range lines {
   216→		line = strings.TrimSpace(line)
   217→		if line == "" {
   218→			continue
   219→		}
   220→
   221→		var entry map[string]interface{}
   222→		if err := json.Unmarshal([]byte(line), &entry); err != nil {
   223→			continue
   224→		}
   225→
   226→		// Check for user message (supports both "human" and "user" types)
   227→		msgType, ok := entry["type"].(string)
   228→		if !ok || (msgType != "human" && msgType != "user") {
   229→			continue
   230→		}
   231→
   232→		// Extract message content
   233→		message, ok := entry["message"].(map[string]interface{})
   234→		if !ok {
   235→			continue
   236→		}
   237→
   238→		// Handle string content
   239→		if content, ok := message["content"].(string); ok && content != "" {
   240→			cleaned := textutil.StripIDEContextTags(content)
   241→			if cleaned != "" {
   242→				prompts = append(prompts, cleaned)
   243→			}
   244→			continue
   245→		}
   246→
   247→		// Handle array content (e.g., multiple text blocks from VSCode)
   248→		if arr, ok := message["content"].([]interface{}); ok {
   249→			var texts []string
   250→			for _, item := range arr {
   251→				if m, ok := item.(map[string]interface{}); ok {
   252→					if m["type"] == "text" {
   253→						if text, ok := m["text"].(string); ok {
   254→							texts = append(texts, text)
   255→						}
   256→					}
   257→				}
   258→			}
   259→			if len(texts) > 0 {
   260→				cleaned := textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   261→				if cleaned != "" {
   262→					prompts = append(prompts, cleaned)
   263→				}
   264→			}
   265→		}
   266→	}
   267→	return prompts
   268→}
   269→
   270→// generateContextFromPrompts generates context.md content from a list of prompts.
   271→func generateContextFromPrompts(prompts []string) []byte {
   272→	if len(prompts) == 0 {
   273→		return nil
   274→	}
   275→
   276→	var buf strings.Builder
   277→	buf.WriteString("# Session Context\n\n")
   278→	buf.WriteString("## User Prompts\n\n")
   279→
   280→	for i, prompt := range prompts {
   281→		// Truncate very long prompts for readability
   282→		displayPrompt := prompt
   283→		if len(displayPrompt) > 500 {
   284→			displayPrompt = displayPrompt[:500] + "..."
   285→		}
   286→		buf.WriteString(fmt.Sprintf("### Prompt %d\n\n", i+1))
   287→		buf.WriteString(displayPrompt)
   288→		buf.WriteString("\n\n")
   289→	}
   290→
   291→	return []byte(buf.String())
   292→}
