   204→// writeStandardCheckpointEntries writes transcript, prompts, context, metadata.json and any additional files.
   205→// If the checkpoint already exists (from a previous session), archives the existing files to a numbered subfolder.
   206→func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   207→	// Check if checkpoint already exists (multi-session support)
   208→	var existingMetadata *CommittedMetadata
   209→	metadataPath := basePath + paths.MetadataFileName
   210→	if entry, exists := entries[metadataPath]; exists {
   211→		// Read existing metadata to get session count
   212→		existing, err := s.readMetadataFromBlob(entry.Hash)
   213→		if err == nil {
   214→			existingMetadata = existing
   215→			// Archive existing session files to numbered subfolder
   216→			s.archiveExistingSession(basePath, existingMetadata, entries)
   217→		}
   218→	}
   219→
   220→	// Write transcript (from in-memory content or file path)
   221→	if err := s.writeTranscript(opts, basePath, entries); err != nil {
   222→		return err
   223→	}
   224→
   225→	// Write prompts
   226→	if len(opts.Prompts) > 0 {
   227→		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
   228→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
   229→		if err != nil {
   230→			return err
   231→		}
   232→		entries[basePath+paths.PromptFileName] = object.TreeEntry{
   233→			Name: basePath + paths.PromptFileName,
   234→			Mode: filemode.Regular,
   235→			Hash: blobHash,
   236→		}
   237→	}
   238→
   239→	// Write context
   240→	if len(opts.Context) > 0 {
   241→		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
   242→		if err != nil {
   243→			return err
   244→		}
   245→		entries[basePath+paths.ContextFileName] = object.TreeEntry{
   246→			Name: basePath + paths.ContextFileName,
   247→			Mode: filemode.Regular,
   248→			Hash: blobHash,
   249→		}
   250→	}
   251→
   252→	// Copy additional metadata files from directory if specified
   253→	if opts.MetadataDir != "" {
   254→		if err := s.copyMetadataDir(opts.MetadataDir, basePath, entries); err != nil {
   255→			return fmt.Errorf("failed to copy metadata directory: %w", err)
   256→		}
   257→	}
   258→
   259→	// Write metadata.json (with merged info if existing metadata present)
   260→	return s.writeMetadataJSON(opts, basePath, entries, existingMetadata)
   261→}
