   263→// writeTranscript writes the transcript file from in-memory content or file path.
   264→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   265→	transcript := opts.Transcript
   266→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   267→		var readErr error
   268→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   269→		if readErr != nil {
   270→			// Non-fatal: transcript may not exist yet
   271→			transcript = nil
   272→		}
   273→	}
   274→	if len(transcript) == 0 {
   275→		return nil
   276→	}
   277→
   278→	blobHash, err := CreateBlobFromContent(s.repo, transcript)
   279→	if err != nil {
   280→		return err
   281→	}
   282→	entries[basePath+paths.TranscriptFileName] = object.TreeEntry{
   283→		Name: basePath + paths.TranscriptFileName,
   284→		Mode: filemode.Regular,
   285→		Hash: blobHash,
   286→	}
   287→
   288→	// Content hash for deduplication
   289→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   290→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   291→	if err != nil {
   292→		return err
   293→	}
   294→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   295→		Name: basePath + paths.ContentHashFileName,
   296→		Mode: filemode.Regular,
   297→		Hash: hashBlob,
   298→	}
   299→	return nil
   300→}
