   302→// writeMetadataJSON writes the metadata.json file for the checkpoint.
   303→// If existingMetadata is provided, merges session info from the previous session(s).
   304→func (s *GitStore) writeMetadataJSON(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingMetadata *CommittedMetadata) error {
   305→	metadata := CommittedMetadata{
   306→		CheckpointID:           opts.CheckpointID,
   307→		SessionID:              opts.SessionID,
   308→		Strategy:               opts.Strategy,
   309→		CreatedAt:              time.Now(),
   310→		CheckpointsCount:       opts.CheckpointsCount,
   311→		FilesTouched:           opts.FilesTouched,
   312→		Agent:                  opts.Agent,
   313→		IsTask:                 opts.IsTask,
   314→		ToolUseID:              opts.ToolUseID,
   315→		SessionCount:           1,
   316→		SessionIDs:             []string{opts.SessionID},
   317→		TranscriptUUIDAtStart:  opts.TranscriptUUIDAtStart,
   318→		TranscriptLinesAtStart: opts.TranscriptLinesAtStart,
   319→		TokenUsage:             opts.TokenUsage,
   320→	}
   321→
   322→	// Merge with existing metadata if present (multi-session checkpoint)
   323→	if existingMetadata != nil {
   324→		// Get existing session count (default to 1 for backwards compat)
   325→		existingCount := existingMetadata.SessionCount
   326→		if existingCount == 0 {
   327→			existingCount = 1
   328→		}
   329→		metadata.SessionCount = existingCount + 1
   330→
   331→		// Merge session IDs
   332→		existingIDs := existingMetadata.SessionIDs
   333→		if len(existingIDs) == 0 {
   334→			// Backwards compat: old metadata only had SessionID
   335→			existingIDs = []string{existingMetadata.SessionID}
   336→		}
   337→		metadata.SessionIDs = append(metadata.SessionIDs[:0], existingIDs...)
   338→		metadata.SessionIDs = append(metadata.SessionIDs, opts.SessionID)
   339→
   340→		// Merge files touched (deduplicated)
   341→		metadata.FilesTouched = mergeFilesTouched(existingMetadata.FilesTouched, opts.FilesTouched)
   342→
   343→		// Sum checkpoint counts
   344→		metadata.CheckpointsCount = existingMetadata.CheckpointsCount + opts.CheckpointsCount
   345→	}
   346→
   347→	metadataJSON, err := json.MarshalIndent(metadata, "", "  ")
   348→	if err != nil {
   349→		return fmt.Errorf("failed to marshal metadata: %w", err)
   350→	}
   351→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   352→	if err != nil {
   353→		return err
   354→	}
   355→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   356→		Name: basePath + paths.MetadataFileName,
   357→		Mode: filemode.Regular,
   358→		Hash: metadataHash,
   359→	}
   360→	return nil
   361→}
   362→
   363→// mergeFilesTouched combines two file lists, removing duplicates.
   364→func mergeFilesTouched(existing, additional []string) []string {
   365→	seen := make(map[string]bool)
   366→	var result []string
   367→
   368→	for _, f := range existing {
   369→		if !seen[f] {
   370→			seen[f] = true
   371→			result = append(result, f)
   372→		}
   373→	}
   374→	for _, f := range additional {
   375→		if !seen[f] {
   376→			seen[f] = true
   377→			result = append(result, f)
   378→		}
   379→	}
   380→
   381→	sort.Strings(result)
   382→	return result
   383→}
