   385→// readMetadataFromBlob reads CommittedMetadata from a blob hash.
   386→func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
   387→	blob, err := s.repo.BlobObject(hash)
   388→	if err != nil {
   389→		return nil, fmt.Errorf("failed to get blob: %w", err)
   390→	}
   391→
   392→	reader, err := blob.Reader()
   393→	if err != nil {
   394→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   395→	}
   396→	defer reader.Close()
   397→
   398→	var metadata CommittedMetadata
   399→	if err := json.NewDecoder(reader).Decode(&metadata); err != nil {
   400→		return nil, fmt.Errorf("failed to decode metadata: %w", err)
   401→	}
   402→
   403→	return &metadata, nil
   404→}
