   406→// archiveExistingSession moves existing session files to a numbered subfolder.
   407→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   408→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   409→	// Determine archive folder number
   410→	sessionCount := existingMetadata.SessionCount
   411→	if sessionCount == 0 {
   412→		sessionCount = 1 // backwards compat
   413→	}
   414→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   415→
   416→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   417→	filesToArchive := []string{
   418→		paths.MetadataFileName,
   419→		paths.TranscriptFileName,
   420→		paths.PromptFileName,
   421→		paths.ContextFileName,
   422→		paths.ContentHashFileName,
   423→	}
   424→
   425→	// Move each file to archive folder
   426→	for _, filename := range filesToArchive {
   427→		srcPath := basePath + filename
   428→		if entry, exists := entries[srcPath]; exists {
   429→			// Add to archive location
   430→			dstPath := archivePath + filename
   431→			entries[dstPath] = object.TreeEntry{
   432→				Name: dstPath,
   433→				Mode: entry.Mode,
   434→				Hash: entry.Hash,
   435→			}
   436→			// Remove from original location (will be overwritten by new session)
   437→			delete(entries, srcPath)
   438→		}
   439→	}
   440→}
