   442→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   443→// Returns sessions ordered by folder index (oldest first).
   444→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int) []ArchivedSession {
   445→	var archived []ArchivedSession
   446→
   447→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   448→	// The most recent session is at the root level (not archived).
   449→	// Session count N means there are N-1 archived sessions.
   450→	for i := 1; i < sessionCount; i++ {
   451→		folderName := strconv.Itoa(i)
   452→
   453→		// Try to get the archived session subtree
   454→		subTree, err := checkpointTree.Tree(folderName)
   455→		if err != nil {
   456→			continue // Folder doesn't exist, skip
   457→		}
   458→
   459→		session := ArchivedSession{
   460→			FolderIndex: i,
   461→		}
   462→
   463→		// Read metadata to get session ID
   464→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   465→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   466→				var metadata CommittedMetadata
   467→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   468→					session.SessionID = metadata.SessionID
   469→				}
   470→			}
   471→		}
   472→
   473→		// Read transcript (try current format first, then legacy)
   474→		if file, fileErr := subTree.File(paths.TranscriptFileName); fileErr == nil {
   475→			if content, contentErr := file.Contents(); contentErr == nil {
   476→				session.Transcript = []byte(content)
   477→			}
   478→		} else if file, fileErr := subTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
   479→			if content, contentErr := file.Contents(); contentErr == nil {
   480→				session.Transcript = []byte(content)
   481→			}
   482→		}
   483→
   484→		// Read prompts
   485→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   486→			if content, contentErr := file.Contents(); contentErr == nil {
   487→				session.Prompts = content
   488→			}
   489→		}
   490→
   491→		// Only add if we got a transcript
   492→		if len(session.Transcript) > 0 {
   493→			archived = append(archived, session)
   494→		}
   495→	}
   496→
   497→	return archived
   498→}
