   542→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   543→// Returns nil, nil if the checkpoint doesn't exist.
   544→//
   545→
   546→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID string) (*ReadCommittedResult, error) {
   547→	_ = ctx // Reserved for future use
   548→
   549→	tree, err := s.getSessionsBranchTree()
   550→	if err != nil {
   551→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   552→	}
   553→
   554→	checkpointPath := paths.CheckpointPath(checkpointID)
   555→	checkpointTree, err := tree.Tree(checkpointPath)
   556→	if err != nil {
   557→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   558→	}
   559→
   560→	result := &ReadCommittedResult{}
   561→
   562→	// Read metadata.json
   563→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   564→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   565→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   566→			json.Unmarshal([]byte(content), &result.Metadata)
   567→			result.Metadata.Strategy = paths.NormalizeStrategyName(result.Metadata.Strategy)
   568→		}
   569→	}
   570→
   571→	// Read transcript (try current format first, then legacy)
   572→	if file, fileErr := checkpointTree.File(paths.TranscriptFileName); fileErr == nil {
   573→		if content, contentErr := file.Contents(); contentErr == nil {
   574→			result.Transcript = []byte(content)
   575→		}
   576→	} else if file, fileErr := checkpointTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
   577→		if content, contentErr := file.Contents(); contentErr == nil {
   578→			result.Transcript = []byte(content)
   579→		}
   580→	}
   581→
   582→	// Read prompts
   583→	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
   584→		if content, contentErr := file.Contents(); contentErr == nil {
   585→			result.Prompts = content
   586→		}
   587→	}
   588→
   589→	// Read context
   590→	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
   591→		if content, contentErr := file.Contents(); contentErr == nil {
   592→			result.Context = content
   593→		}
   594→	}
   595→
   596→	// Read archived sessions if this is a multi-session checkpoint
   597→	if result.Metadata.SessionCount > 1 {
   598→		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount)
   599→	}
   600→
   601→	return result, nil
   602→}
