   604→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   605→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   606→//
   607→
   608→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   609→	_ = ctx // Reserved for future use
   610→
   611→	tree, err := s.getSessionsBranchTree()
   612→	if err != nil {
   613→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   614→	}
   615→
   616→	var checkpoints []CommittedInfo
   617→
   618→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   619→	for _, bucketEntry := range tree.Entries {
   620→		if bucketEntry.Mode != filemode.Dir {
   621→			continue
   622→		}
   623→		// Bucket should be 2 hex chars
   624→		if len(bucketEntry.Name) != 2 {
   625→			continue
   626→		}
   627→
   628→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   629→		if treeErr != nil {
   630→			continue
   631→		}
   632→
   633→		// Each entry in the bucket is the remaining part of the checkpoint ID
   634→		for _, checkpointEntry := range bucketTree.Entries {
   635→			if checkpointEntry.Mode != filemode.Dir {
   636→				continue
   637→			}
   638→
   639→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   640→			if cpTreeErr != nil {
   641→				continue
   642→			}
   643→
   644→			// Reconstruct checkpoint ID: <bucket><remaining>
   645→			checkpointID := bucketEntry.Name + checkpointEntry.Name
   646→
   647→			info := CommittedInfo{
   648→				CheckpointID: checkpointID,
   649→			}
   650→
   651→			// Get details from metadata file
   652→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   653→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   654→					var metadata CommittedMetadata
   655→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   656→						info.SessionID = metadata.SessionID
   657→						info.CreatedAt = metadata.CreatedAt
   658→						info.CheckpointsCount = metadata.CheckpointsCount
   659→						info.FilesTouched = metadata.FilesTouched
   660→						info.Agent = metadata.Agent
   661→						info.IsTask = metadata.IsTask
   662→						info.ToolUseID = metadata.ToolUseID
   663→						info.SessionCount = metadata.SessionCount
   664→						info.SessionIDs = metadata.SessionIDs
   665→					}
   666→				}
   667→			}
   668→
   669→			checkpoints = append(checkpoints, info)
   670→		}
   671→	}
   672→
   673→	// Sort by time (most recent first)
   674→	sort.Slice(checkpoints, func(i, j int) bool {
