   744→// CreateBlobFromContent creates a blob object from in-memory content.
   745→// Exported for use by strategy package (session_test.go)
   746→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
   747→	obj := repo.Storer.NewEncodedObject()
   748→	obj.SetType(plumbing.BlobObject)
   749→	obj.SetSize(int64(len(content)))
   750→
   751→	writer, err := obj.Writer()
   752→	if err != nil {
   753→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
   754→	}
   755→
   756→	_, err = writer.Write(content)
   757→	if err != nil {
   758→		_ = writer.Close()
   759→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
   760→	}
   761→	if err := writer.Close(); err != nil {
   762→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
   763→	}
   764→
   765→	hash, err := repo.Storer.SetEncodedObject(obj)
   766→	if err != nil {
   767→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
   768→	}
   769→	return hash, nil
   770→}
