   772→// copyMetadataDir copies all files from a directory to the checkpoint path.
   773→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
   774→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
   775→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
   776→		if err != nil {
   777→			return err
   778→		}
   779→		if info.IsDir() {
   780→			return nil
   781→		}
   782→
   783→		// Skip symlinks to prevent reading files outside the metadata directory.
   784→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
   785→		// then be captured in the checkpoint and stored in git history.
   786→		if info.Mode()&os.ModeSymlink != 0 {
   787→			return nil
   788→		}
   789→
   790→		// Get relative path within metadata dir
   791→		relPath, err := filepath.Rel(metadataDir, path)
   792→		if err != nil {
   793→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
   794→		}
   795→
   796→		// Prevent path traversal via symlinks pointing outside the metadata dir
   797→		if strings.HasPrefix(relPath, "..") {
   798→			return fmt.Errorf("path traversal detected: %s", relPath)
   799→		}
   800→
   801→		// Create blob from file
   802→		blobHash, mode, err := createBlobFromFile(s.repo, path)
   803→		if err != nil {
   804→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
   805→		}
   806→
   807→		// Store at checkpoint path
   808→		fullPath := basePath + relPath
   809→		entries[fullPath] = object.TreeEntry{
   810→			Name: fullPath,
   811→			Mode: mode,
   812→			Hash: blobHash,
   813→		}
   814→
   815→		return nil
   816→	})
   817→	if err != nil {
   818→		return fmt.Errorf("failed to walk metadata directory: %w", err)
   819→	}
   820→	return nil
   821→}
